// The clinic's own domain. Staff addresses don't belong on a client's form.
const CLINIC_DOMAIN = '@demo-clinic.example';

export const validators = [
  {
    field: 'email',
    validate: ({ value }) =>
      typeof value === 'string' && value.trim().toLowerCase().endsWith(CLINIC_DOMAIN)
        ? "Enter your own email address, not the clinic's."
        : null,
  },
];

export const validators = [
  {
    field: 'therapy_visits',
    validate: ({ value }) => (typeof value === 'number' && !Number.isInteger(value) ? 'Enter a whole number.' : null),
  },
];

export const validators = [
  {
    field: 'date_of_birth',
    // Dates are YYYY-MM-DD text, so they compare as text. Today is in UTC.
    validate: ({ value }) =>
      typeof value === 'string' && value > new Date().toISOString().slice(0, 10) ? "Date of birth can't be in the future." : null,
  },
];

// Times are HH:MM text, so they compare as text.
const OPENS = '08:00';
const CLOSES = '18:00';

export const validators = [
  {
    field: 'preferred_time',
    validate: ({ value }) =>
      typeof value === 'string' && (value < OPENS || value > CLOSES) ? 'Choose a time between 08:00 and 18:00.' : null,
  },
];

// The referrals this clinic books online. It books the others by phone.
const BOOKED_ONLINE = ['self', 'family_member', 'primary_care_provider', 'therapist_or_counselor'];

export const validators = [
  {
    field: 'referral_source',
    validate: ({ value }) =>
      typeof value === 'string' && !BOOKED_ONLINE.includes(value) ? 'Call the front desk to book this referral.' : null,
  },
];

export const validators = [
  {
    field: 'available_days',
    validate: ({ value }) => (Array.isArray(value) && value.length < 2 ? 'Choose at least two days.' : null),
  },
];
